@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p class="lead">Explore our departments and courses. Find the right classes for your academic journey.</p>
    </div>

    <section class="featured-section">
        <h2>Featured Courses</h2>
        <div class="course-grid">
            @foreach (var course in featuredCourses)
            {
                <div class="course-card">
                    <span class="badge">@course.CourseCode</span>
                    <h3>@course.Title</h3>
                    <p>@course.DepartmentName &bull; @course.Credits credits</p>
                    <p class="schedule">@course.Schedule</p>
                    <a href="/courses/@course.Id" class="btn btn-primary">View Details</a>
                </div>
            }
        </div>
    </section>

    <section class="departments-section">
        <h2>Departments</h2>
        <div class="dept-grid">
            @foreach (var dept in departments)
            {
                <a href="/courses?departmentId=@dept.Id" class="dept-card">
                    <h3>@dept.Name</h3>
                    <p>@dept.Description</p>
                </a>
            }
        </div>
    </section>

    <section class="quick-links">
        <a href="/courses" class="btn btn-secondary">Browse All Courses</a>
        <a href="/enroll" class="btn btn-secondary">Enrollment Request</a>
    </section>
</div>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Course Catalog</PageTitle>

<div class="container">
    <h1>Course Catalog</h1>

    <div class="filters">
        <input type="text" @bind="searchTerm" @bind:event="oninput" placeholder="Search by title, code, or instructor..." class="search-input" />

        <select @bind="selectedDepartmentId" class="filter-select">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>

    <div class="course-list">
        @if (filteredCourses.Any())
        {
            @foreach (var course in filteredCourses)
            {
                <div class="course-row">
                    <div class="course-info">
                        <span class="course-code">@course.CourseCode</span>
                        <a href="/courses/@course.Id" class="course-title">@course.Title</a>
                        <span class="course-meta">@course.DepartmentName &bull; @course.Credits credits &bull; @course.InstructorName</span>
                    </div>
                    <div class="course-schedule">@course.Schedule</div>
                </div>
            }
        }
        else
        {
            <p class="no-results">No courses found matching your criteria.</p>
        }
    </div>
</div>

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; ApplyFilters(); }
    }

    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; ApplyFilters(); }
    }

    [SupplyParameterFromQuery(Name = "departmentId")]
    public int? DepartmentIdFromQuery { get; set; }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();

        if (DepartmentIdFromQuery.HasValue)
            _selectedDepartmentId = DepartmentIdFromQuery.Value;

        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = CatalogService.GetCourses(
            string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm,
            _selectedDepartmentId > 0 ? _selectedDepartmentId : null);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>
    <p>Submit your enrollment request using the form below. You will be contacted by the registrar's office.</p>

    @if (submitted)
    {
        <div class="success-message">
            <h2>Request Submitted!</h2>
            <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for <strong>@selectedCourseName</strong> has been received.</p>
            <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="enrollment-form">
            <DataAnnotationsValidator />
            <ValidationSummary />

            <div class="form-group">
                <label for="studentName">Full Name</label>
                <InputText id="studentName" @bind-Value="model.StudentName" class="form-control" />
                <ValidationMessage For="() => model.StudentName" />
            </div>

            <div class="form-group">
                <label for="studentId">Student ID</label>
                <InputText id="studentId" @bind-Value="model.StudentId" class="form-control" placeholder="e.g., STU12345" />
                <ValidationMessage For="() => model.StudentId" />
            </div>

            <div class="form-group">
                <label for="courseSelect">Course</label>
                <InputSelect id="courseSelect" @bind-Value="model.CourseId" class="form-control">
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id">@course.CourseCode – @course.Title</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.CourseId" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Request</button>
        </EditForm>
    }
</div>

@code {
    [SupplyParameterFromQuery(Name = "courseId")]
    public int? CourseIdFromQuery { get; set; }

    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    private List<Course> courses = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (CourseIdFromQuery.HasValue && model.CourseId == 0)
            model.CourseId = CourseIdFromQuery.Value;
    }

    private void HandleSubmit()
    {
        var success = CatalogService.SubmitEnrollmentRequest(model);
        if (success)
        {
            var course = CatalogService.GetCourse(model.CourseId);
            selectedCourseName = course is not null ? $"{course.CourseCode} – {course.Title}" : "Selected Course";
            submitted = true;
        }
    }
}

